# SPDX-License-Identifier: MIT
# Trusted controls for the rollback faults; exits 1 (failing setup) if a
# mechanism does not behave as the case assumes.
import errno, os, resource, sys
mode, args = sys.argv[1], sys.argv[2:]


def die(text):
    print(mode + ": CONTROL FAILED: " + text)
    sys.exit(1)


if mode == "readonly-dir":
    st = os.stat(args[0])
    if st.st_uid != os.geteuid() or (st.st_mode & 0o777) != 0o555:
        die("directory owner/mode %d/%o" % (st.st_uid, st.st_mode & 0o777))
    try:
        os.close(os.open(os.path.join(args[0], ".probe"), os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600))
    except OSError as exc:
        if exc.errno != errno.EACCES:
            die("create gave %s" % errno.errorcode.get(exc.errno))
        print(mode + ": caller-owned 0555 directory, file creation -> EACCES")
    else:
        die("file creation succeeded")
elif mode == "fsize":
    lim = resource.getrlimit(resource.RLIMIT_FSIZE)[0]
    if lim != int(args[1]):
        die("RLIMIT_FSIZE %r, expected %s" % (lim, args[1]))
    path = os.path.join(args[0], ".fsize-probe")
    fd = os.open(path, os.O_CREAT | os.O_TRUNC | os.O_WRONLY, 0o600)
    n = os.write(fd, b"a" * (lim + 512))
    if n != lim:
        die("write returned %d, expected short %d" % (n, lim))
    try:
        os.write(fd, b"a")
    except OSError as exc:
        if exc.errno != errno.EFBIG:
            die("second write gave %s" % errno.errorcode.get(exc.errno))
    else:
        die("second write succeeded")
    os.close(fd)
    os.unlink(path)
    print(mode + ": limit %d, over-limit write short then EFBIG" % lim)
elif mode == "rename-onto-dir":
    src = os.path.join(os.path.dirname(args[0]), ".rename-probe")
    open(src, "w").close()
    try:
        os.rename(src, args[0])
    except OSError as exc:
        if exc.errno != errno.EISDIR:
            die("rename gave %s" % errno.errorcode.get(exc.errno))
        print(mode + ": rename(file, non-empty directory) -> EISDIR")
    else:
        die("rename succeeded")
    os.unlink(src)
else:
    die("unknown mode")
